def body(handle, i):
    d = P[handle]
    g = lambda k: d[k][i]
    li = ''.join('<li>%s：%s</li>' % (H[k][i], g(k)) if i in (0, 2) else '<li>%s: %s</li>' % (H[k][i], g(k)) for k in ['mat', 'el', 'land', 'bless'])
    return ('<p><em>%s</em></p><h3>%s</h3><p>%s</p><p>%s</p><h3>%s</h3><p>%s</p><h3>%s</h3><ul>%s</ul><h3>%s</h3><p>%s</p><p><small>%s</small></p>'
            % (g('tag'), H['origin'][i], g('origin'), g('design'), H['meaning'][i], g('meaning'), H['piece'][i], li, H['wear'][i], g('wear'), DISC[i]))
